import { fireEvent, render, screen } from '@testing-library/react';
import { describe, expect, it, vi } from 'vitest';
import UndoToast from './UndoToast';

describe('UndoToast', () => {
  it('shows the card name and fires onDismiss once after 6000 ms', () => {
    const onUndo = vi.fn();
    const onDismiss = vi.fn();
    vi.useFakeTimers();

    render(
      <UndoToast cardName="Test Spell" instanceId="test-1" onUndo={onUndo} onDismiss={onDismiss} />,
    );

    expect(screen.getByText('Test Spell removed')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /Undo/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /Dismiss/i })).toBeInTheDocument();

    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(6000);

    expect(onDismiss).toHaveBeenCalledTimes(1);
  });

  it('a second removal with the same cardName but different instanceId receives its own full AUTO_DISMISS_MS window', () => {
    const onUndo = vi.fn();
    const onDismiss = vi.fn();
    vi.useFakeTimers();

    const firstInstanceId = 'first-instance';
    const secondInstanceId = 'second-instance';
    const cardName = 'Suspended Spell';

    render(
      <UndoToast cardName={cardName} instanceId={firstInstanceId} onUndo={onUndo} onDismiss={onDismiss} />,
    );

    const firstToastEl = screen.getByText(`${cardName} removed`);
    expect(firstToastEl).toBeInTheDocument();

    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(5000);

    expect(onDismiss).not.toHaveBeenCalled();

    rerender(
      <UndoToast cardName={cardName} instanceId={secondInstanceId} onUndo={onUndo} onDismiss={onDismiss} />,
    );

    const secondToastEl = screen.getByText(`${cardName} removed`);
    expect(secondToastEl).toBeInTheDocument();

    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(5000);

    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(1000);

    expect(onDismiss).toHaveBeenCalledTimes(1);
  });
});

