import { describe, expect, it, vi } from 'vitest';
import { render, screen, cleanup } from '@testing-library/react';
import UndoToast from './UndoToast';

describe('UndoToast', () => {
  describe('basic dismiss timer', () => {
    it('shows the card name and fires onDismiss once after 6000 ms', () => {
      const onUndo = vi.fn();
      const onDismiss = vi.fn();

      render(<UndoToast cardName="Test Spell" instanceId="test-1" onUndo={onUndo} onDismiss={onDismiss} />);

      expect(screen.getByText('Test Spell removed')).toBeInTheDocument();
      expect(screen.getByRole('button', { name: /Undo/i })).toBeInTheDocument();
      expect(screen.getByRole('button', { name: /Dismiss/i })).toBeInTheDocument();

      expect(onDismiss).not.toHaveBeenCalled();

      cleanup();

      vi.useFakeTimers();
      render(<UndoToast cardName="Test Spell" instanceId="test-1" onUndo={vi.fn()} onDismiss={vi.fn()} />);
      cleanup();

      vi.advanceTimersByTime(6000);

      expect(onDismiss).toHaveBeenCalledTimes(1);
    });
  });

  describe('different instanceId with same cardName', () => {
    it('a second removal with the same cardName but different instanceId receives its own full 6000 ms', () => {
      const cardName = 'Suspended Spell';
      const firstInstanceId = 'first-instance';
      const secondInstanceId = 'second-instance';

      const firstToastOnDismiss = vi.fn();
      const secondToastOnDismiss = vi.fn();

      // First render
      render(<UndoToast cardName={cardName} instanceId={firstInstanceId} onUndo={vi.fn()} onDismiss={firstToastOnDismiss} />);

      cleanup();

      vi.useFakeTimers();

      // Advance to 5s without dismissing
      vi.advanceTimersByTime(5000);

      expect(firstToastOnDismiss).not.toHaveBeenCalled();

      // Switch to the same cardName, different instanceId
      render(<UndoToast cardName={cardName} instanceId={secondInstanceId} onUndo={vi.fn()} onDismiss={secondToastOnDismiss} />);

      // Second toast is shown with the same card name
      expect(screen.getByText(`${cardName} removed`));

      // Give the second toast 5 seconds
      vi.advanceTimersByTime(5000);

      expect(secondToastOnDismiss).not.toHaveBeenCalled();

      // Advance 1 second: at 1s before 6s, the second toast should not disappear
      vi.advanceTimersByTime(1000);

      // Second toast should have dismissed (total = 6s from second render)
      expect(secondToastOnDismiss).toHaveBeenCalledTimes(1);

      // The first toast's onDismiss should not have been called
      expect(firstToastOnDismiss).not.toHaveBeenCalled();
    });
  });
});

